import sqlite3
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        action TEXT,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('q', '')

    # Restrict searchable fields to prevent accessing sensitive columns
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid search field'}), 400

    # Log the search for compliance
    log_query = f"INSERT INTO audit_log (action, details) VALUES ('search', 'field={field}, q={value}')"
    db = get_db()
    try:
        db.execute(log_query)
        db.commit()
    except Exception as e:
        app.logger.warning(f"Audit log failed: {e}")

    # Perform the actual search using parameterized query
    search_query = f"SELECT username, email, role FROM users WHERE {field} LIKE ?"
    try:
        results = db.execute(search_query, (f'%{value}%',)).fetchall()
        return jsonify({'results': [dict(r) for r in results]})
    except Exception as e:
        return jsonify({'error': 'Search failed'}), 500

@app.route('/api/users', methods=['POST'])
def create_user():
    """Create a new user account."""
    data = request.get_json()
    if not data or 'username' not in data or 'email' not in data:
        return jsonify({'error': 'Missing required fields'}), 400

    username = data['username']
    email = data['email']
    api_key = os.urandom(16).hex()

    db = get_db()
    try:
        db.execute(
            "INSERT INTO users (username, email, api_key) VALUES (?, ?, ?)",
            (username, email, api_key)
        )
        db.commit()
        return jsonify({'username': username, 'api_key': api_key}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already exists'}), 409

@app.route('/api/users/<username>/promote', methods=['PUT'])
def promote_user(username):
    """Promote user to admin role. Requires internal service token."""
    token = request.headers.get('X-Service-Token', '')
    if token != os.environ.get('INTERNAL_SERVICE_TOKEN', ''):
        return jsonify({'error': 'Unauthorized'}), 403

    db = get_db()
    db.execute("UPDATE users SET role = 'admin' WHERE username = ?", (username,))
    db.commit()
    return jsonify({'status': 'promoted'})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
